/**
 * Identifies the unit system used by a HID report item.
 * @see https://wicg.github.io/webhid/#dom-hidunitsystem
 */
export type HIDUnitSystem =
  | "none"
  | "si-linear"
  | "si-rotation"
  | "english-linear"
  | "english-rotation"
  | "vendor-defined"
  | "reserved";

