/**
 * A filter used to narrow the set of HID devices shown in the chooser.
 * All specified fields must match for a device to be included.
 * @see https://wicg.github.io/webhid/#dom-hiddevicefilter
 */
export interface HIDDeviceFilter {
  /** USB vendor identifier (0x0000 – 0xFFFF). */
  vendorId?: number;
  /** USB product identifier (0x0000 – 0xFFFF). */
  productId?: number;
  /** HID usage page number. */
  usagePage?: number;
  /** HID usage number within the given usagePage. */
  usage?: number;
}

/**
 * Options passed to {@link HID.requestDevice}.
 * @see https://wicg.github.io/webhid/#dom-hiddevicerequestoptions
 */
export interface HIDDeviceRequestOptions {
  /**
   * An array of filters.  A device is shown in the chooser if it matches
   * *at least one* filter.  Pass an empty array to show all devices.
   */
  filters: HIDDeviceFilter[];
  /**
   * An optional array of filters used to *exclude* devices.  A device that
   * matches any exclusion filter is removed even when it matched a filter in
   * `filters`.
   */
  exclusionFilters?: HIDDeviceFilter[];
}

