/**
 * A single item parsed from a HID report descriptor.
 * @see https://wicg.github.io/webhid/#dom-hidreportitem
 */
export interface HIDReportItem {
  /** Whether the item is a constant (true) or data (false). */
  isAbsolute?: boolean;
  /** Whether the data is represented as an array or bitmap. */
  isArray?: boolean;
  /** Whether the buffer format is buffered bytes (true) or bit field (false). */
  isBufferedBytes?: boolean;
  /** Whether the item represents a constant value. */
  isConstant?: boolean;
  /** Whether the usages listed below are linear controls. */
  isLinear?: boolean;
  /** Whether the input has no preferred state to which it returns when the user is not physically interacting with the control. */
  isNonLinear?: boolean;
  /** Whether the control has a preferred state (e.g. a latching push button). */
  isNoPreferred?: boolean;
  /** Whether the null state is a valid output. */
  isNullable?: boolean;
  /** Whether the control emits a fixed-size stream of bytes. */
  isRange?: boolean;
  /** Whether the Usage minimum and maximum define a range of valid usages. */
  isVolatile?: boolean;
  /** Whether the data wraps around past the logical minimum/maximum. */
  isWrap?: boolean;

  /** Array of usage values applicable to this item. */
  usages?: number[];
  /** Inclusive start of a usage range (when `isRange` is true). */
  usageMinimum?: number;
  /** Inclusive end of a usage range (when `isRange` is true). */
  usageMaximum?: number;

  /** Unsigned minimum value reported by the control in its logical coordinate system. */
  reportCount?: number;
  /** Bit size of each data field in the report. */
  reportSize?: number;

  /** Minimum value in the logical coordinate system. */
  logicalMinimum?: number;
  /** Maximum value in the logical coordinate system. */
  logicalMaximum?: number;
  /** Minimum value in the physical coordinate system. */
  physicalMinimum?: number;
  /** Maximum value in the physical coordinate system. */
  physicalMaximum?: number;

  /** Identifies the unit system (e.g. "si-linear"). */
  unitSystem?: HIDUnitSystem;
  /** Magnitude of the units in the lower nibble of the unit value. */
  unitFactorLengthExponent?: number;
  /** Magnitude of the units in the next nibble of the unit value. */
  unitFactorMassExponent?: number;
  unitFactorTimeExponent?: number;
  unitFactorTemperatureExponent?: number;
  unitFactorCurrentExponent?: number;
  unitFactorLuminousIntensityExponent?: number;

  /** Strings that describe this item (from the string descriptor). */
  strings?: string[];
  /** Indices into the device's string descriptors. */
  hasNull?: boolean;
}

/**
 * Describes a single HID report (Input, Output, or Feature).
 * @see https://wicg.github.io/webhid/#dom-hidreportinfo
 */
export interface HIDReportInfo {
  /**
   * A one-byte report identifier.  0 indicates that the device does not
   * use report IDs.
   */
  reportId: number;
  /** Parsed items contained within this report. */
  items: HIDReportItem[];
}

/**
 * Describes a HID collection (top-level or nested) as parsed from the
 * device's report descriptor.
 * @see https://wicg.github.io/webhid/#dom-hidcollectioninfo
 */
export interface HIDCollectionInfo {
  /** HID usage page for this collection. */
  usagePage: number;
  /** HID usage for this collection. */
  usage: number;
  /** Nested collections within this collection. */
  children: HIDCollectionInfo[];
  /** Input reports in this collection. */
  inputReports: HIDReportInfo[];
  /** Output reports in this collection. */
  outputReports: HIDReportInfo[];
  /** Feature reports in this collection. */
  featureReports: HIDReportInfo[];
}

