/**
 * Entry point for the WebHID API.  Accessible via `navigator.hid` (Window
 * context) or `navigator.hid` inside a Dedicated/Service Worker.
 *
 * Inherits from {@link EventTarget}.
 *
 * @see https://developer.mozilla.org/en-US/docs/Web/API/HID
 * @see https://wicg.github.io/webhid/#dom-hid
 *
 * @example
 * ```ts
 * // Enumerate previously granted devices
 * const devices: HIDDevice[] = await navigator.hid.getDevices();
 *
 * // Request access to a new device
 * const [device] = await navigator.hid.requestDevice({ filters: [] });
 *
 * // Listen for hot-plug events
 * navigator.hid.addEventListener("connect", (e: HIDConnectionEvent) => {
 *   console.log("connected:", e.device.productName);
 * });
 * ```
 */
export interface HID extends EventTarget {
  // ---- Events ----

  /**
   * Fired when a HID device matching a previously granted permission becomes
   * available (e.g. plugged in).
   */
  onconnect: ((this: HID, ev: HIDConnectionEvent) => unknown) | null;

  /**
   * Fired when a previously available HID device is no longer available
   * (e.g. unplugged).
   */
  ondisconnect: ((this: HID, ev: HIDConnectionEvent) => unknown) | null;

  // ---- Methods ----

  /**
   * Returns an array of {@link HIDDevice} objects representing all HID
   * devices that the page already has permission to access.
   *
   * @returns A Promise that resolves with an array of {@link HIDDevice}.
   */
  getDevices(): Promise<HIDDevice[]>;

  /**
   * Prompts the user to select a HID device.  Only callable from a Window
   * context with a user gesture.
   *
   * @param options - Filters controlling which devices appear in the chooser.
   * @returns A Promise that resolves with the array of {@link HIDDevice}
   *   objects selected by the user (may be empty if the user cancels).
   */
  requestDevice(options: HIDDeviceRequestOptions): Promise<HIDDevice[]>;

  // ---- Typed event listener overloads ----

  addEventListener(
    type: "connect",
    listener: (this: HID, ev: HIDConnectionEvent) => unknown,
    options?: boolean | AddEventListenerOptions,
  ): void;
  addEventListener(
    type: "disconnect",
    listener: (this: HID, ev: HIDConnectionEvent) => unknown,
    options?: boolean | AddEventListenerOptions,
  ): void;
  addEventListener(
    type: string,
    listener: EventListenerOrEventListenerObject,
    options?: boolean | AddEventListenerOptions,
  ): void;

  removeEventListener(
    type: "connect",
    listener: (this: HID, ev: HIDConnectionEvent) => unknown,
    options?: boolean | EventListenerOptions,
  ): void;
  removeEventListener(
    type: "disconnect",
    listener: (this: HID, ev: HIDConnectionEvent) => unknown,
    options?: boolean | EventListenerOptions,
  ): void;
  removeEventListener(
    type: string,
    listener: EventListenerOrEventListenerObject,
    options?: boolean | EventListenerOptions,
  ): void;
}

